import numpy as np
from scipy import ndimage

def solve(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0]); bg=g[0][0]
    lab,n=ndimage.label(np.array(g)!=bg)
    multi=[]; singles=[]
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        if len(ys)>1:
            multi.append((set(g[y,x].tolist() for y,x in zip(ys,xs)), tuple(sorted(zip(ys.tolist(),xs.tolist())))))
        else:
            singles.append((int(ys[0]),int(xs[0]),g[ys[0],xs[0]]))
    o=[r[:] for r in g]
    if not multi:
        for ty,tx,c in singles:
            if c==2 and ty+1<H and tx+1<W: o[ty+1][tx+1]=7
            elif c==3 and ty+1<H and tx+1<W: o[ty+1][tx+1]=8
        return o
    tc=max(multi,key=lambda m:len(m[1]))
    tcol=set(tc[0])
    mkc=None
    for col in tcol:
        if any(c==col for _,_,c in singles):
            mkc=col; break
    mkpos=[(y,x) for y,x in tc[1] if g[y,x]==mkc]
    myt,mxt=mkpos[0]
    tpl={(y-tc[2],x-tc[3]) for y,x in tc[1]}
    for sy,sx,c in singles:
        for dy,dx in sorted(tpl):
            ny,nx=sy+(dy-myt),sx+(dx-mxt)
            if 0<=ny<H and 0<=nx<W: o[ny][nx]=g[mkpos[0][0]+ (dy-myt)+0 if False else sy+ (sy-sy)]  # placeholder
    return o

