import numpy as np, collections
from scipy import ndimage
def norm(off):
    rs=[a for a,b,_ in off]; cs=[b for a,b,_ in off]
    return tuple(sorted(((a-min(rs),b-min(cs),v) for a,b,v in off)))
def transforms(cells):
    res=set(); cur=[(int(a),int(b),int(v)) for a,b,v in cells]
    for _ in range(4):
        cur=[(b,-a,v) for a,b,v in cur]
        res.add(norm(cur))
        for _ in range(2):
            cur=[(a,-b,v) for a,b,v in cur]
            res.add(norm(cur))
    return [list(x) for x in res]
def analyze(g):
    A=np.array(g); H,W=A.shape
    bg=int(collections.Counter(A.flatten()).most_common(1)[0][0])
    lab,n=ndimage.label(A!=bg,structure=np.ones((3,3)))
    sizes={int(i):int(np.sum(lab==i)) for i in range(1,n+1)}
    comps=[]
    for i in range(1,n+1):
        if sizes[i]<=1: continue
        pts=list(map(tuple,np.argwhere(lab==i)))
        cnt=collections.Counter(int(A[p[0]][p[1]]) for p in pts)
        rare=[v for v,c_ in cnt.items() if c_==1]
        anch=None
        if len(rare)==1: anch=rare[0]
        else: anch=min(cnt,key=lambda v:cnt[v])
        if cnt[anch]!=1: continue
        anchor=[p for p in pts if int(A[p[0]][p[1]])==anch][0]
        comp=[(p[0]-anchor[0],p[1]-anchor[1],int(A[p[0]][p[1]])) for p in pts]
        comps.append((anch,tuple(transforms(comp)),anchor))
    singles=[(r,c,int(A[r][c])) for r in range(H) for c in range(W) if sizes.get(int(lab[r][c]),0)==1]
    return A,bg,singles,comps
def solve(g, fill_bg_only=True, allow_overlap=False, orient='first'):
    A,bg,singles,comps=analyze(g)
    H,W=A.shape
    out=[[int(x) for x in row] for row in A.tolist()]
    painted=[[False]*W for _ in range(H)]
    for sr,sc,scol in sorted(singles):
        cands=[]
        for anch,tpls,anchor in comps:
            if anch!=scol: continue
            for T in tpls:
                dr,dc=sr-anchor[0], sc-anchor[1]
                ok=True; newcells=[]
                for aa,bb,v in T:
                    rr,cc=aa+dr,bb+dc
                    if not(0<=rr<H and 0<=cc<W): ok=False;break
                    if fill_bg_only and A[rr][cc]!=bg: ok=False;break
                    newcells.append((rr,cc,v))
                if ok: cands.append(T)
        if not cands: continue
        if orient=='all':
            for T in cands:
