    szs = {int(i): int(np.sum(lab == i)) for i in range(1, n + 1)}

    co = []
    for i in range(1, n + 1):
        if szs[i] <= 1: continue
        pts = [(r, c) for r in range(H) for c in range(W) if lab[r][c] == i]
        cnt = collections.Counter(int(A[r][c]) for r, c in pts)
        if min(cnt.values()) != 1: continue
        anc = [v for v, _ in cnt.items() if _ == 1][0]
        ap = [p for p in pts if A[p[0]][p[1]] == anc][0]
        offsets = [
            (int(p[0]-ap[0]), int(p[1]-ap[1]), int(A[p[0]][p[1]]))
            for p in pts if not (p[0]==ap[0] and p[1]==ap[1])
        ]
        # convert to explicit nested tuples so there's no ambiguity
        tups = [(off_dc if False else off_dc if False else None, None, None)]
        tups = [(a, b, v) for a, b, v in offsets]
        co.append((anc, tuple(tups)))

    singles = sorted(
        [(int(r), int(c), int(A[r][c])) for r in range(H) for c in range(W) if szs.get(int(lab[r][c]), 0) == 1],
    )

    out = [[int(x) for x in row] for row in A.tolist()]
    for sr, sc, scol in singles:
        best = None; bcscore = -1
        for anch, tpl in co:
            if anch != scol: continue
