            for T in Tlist:
                score = sum(1 for a, b, v in T if 0 <= sr+a < H and 0 <= sc+b < W and int(A[sr+a][sc+b]) == bg)
                if score > bcscore:
                    bcscore = score; best = T
        if best is None: continue
        for a, b, v in best:
            rr, cc = sr + a, sc + b
            if 0 <= rr < H and 0 <= cc < W and int(A[rr][cc]) == bg:
                out[rr][cc] = v
    return out


