    szs={int(i):int(np.sum(lab==i)) for i in range(1,n+1)}
    info=[]
    for i in range(1,n+1):
        if szs[i]<=1: continue
        pts=[(r,c) for r in range(H) for c in range(W) if lab[r][c]==i]
        cnt=collections.Counter(int(A[r][c]) for r,c in pts)
        anc_cands=[v for v,_ in cnt.items() if _==1]
        if len(anc_cands)!=1: continue
        anc=anc_cands[0]
        ap=[p for p in pts if A[p[0]][p[1]]==anc][0]
        tpl=tuple((int(p[0]-ap[0]),int(p[1]-ap[1]),int(A[p[0]][p[1]])) for p in pts if not(p[0]==ap[0] and p[1]==ap[1]))
        info.append((anc,tpl))
    singles=[(int(r),int(c),int(A[r][c])) for r in range(H) for c in range(W) if szs.get(int(lab[r][c]),0)==1]
    return bg,info,singles

def dihedral(tpl):
    out=[];cur=list(tpl)
    for _ in range(4):
        for t_ in cur: out.append(tuple(t_))
        cur=[(t_[1],-t_[0],t_[2]) for t_ in cur]
    return list(set(out))

